"""Frame-limited garment position override; UVs and original mesh stay intact."""
import bpy
import numpy as np


def install(obj,points,frame=325):
    m=np.linalg.inv(np.array(obj.matrix_world));points=points@m[:3,:3].T+m[:3,3];mesh=bpy.data.meshes.new(obj.name+'_StaticContactPositions');mesh.from_pydata(points.tolist(),[],[]);helper=bpy.data.objects.new(obj.name+'_StaticContactPositions',mesh);bpy.context.scene.collection.objects.link(helper);helper.matrix_world=obj.matrix_world.copy();helper.hide_render=True;helper.hide_set(True);helper['outfit_backup']=True
    tree=bpy.data.node_groups.new(obj.name+'_StaticContactPositions','GeometryNodeTree');tree.interface.new_socket(name='Geometry',in_out='INPUT',socket_type='NodeSocketGeometry');tree.interface.new_socket(name='Geometry',in_out='OUTPUT',socket_type='NodeSocketGeometry');n,l=tree.nodes,tree.links;inp=n.new('NodeGroupInput');info=n.new('GeometryNodeObjectInfo');info.transform_space='RELATIVE';info.inputs['Object'].default_value=helper;pos=n.new('GeometryNodeInputPosition');idx=n.new('GeometryNodeInputIndex');sample=n.new('GeometryNodeSampleIndex');sample.data_type='FLOAT_VECTOR';sample.domain='POINT';l.new(info.outputs['Geometry'],sample.inputs['Geometry']);l.new(pos.outputs[0],sample.inputs['Value']);l.new(idx.outputs[0],sample.inputs['Index']);time=n.new('GeometryNodeInputSceneTime');compare=n.new('FunctionNodeCompare');compare.data_type='FLOAT';compare.operation='EQUAL';compare.inputs['B'].default_value=float(frame);compare.inputs['Epsilon'].default_value=.001;l.new(time.outputs['Frame'],compare.inputs['A']);move=n.new('GeometryNodeSetPosition');l.new(inp.outputs['Geometry'],move.inputs['Geometry']);l.new(sample.outputs['Value'],move.inputs['Position']);l.new(compare.outputs['Result'],move.inputs['Selection']);output=n.new('NodeGroupOutput');l.new(move.outputs['Geometry'],output.inputs['Geometry']);modifier=obj.modifiers.new('Static garment contact positions','NODES');modifier.node_group=tree;return modifier
